const fileTypeIconMap = {
    jpg: 'image',
    jpeg: 'image',
    png: 'image',
    gif: 'image',
    ico: 'image',
    bmp: 'image',
    tif: 'image',
    tiff: 'image',
    pdf: 'file-type-pdf',
    doc: 'file-type-doc',
    docx: 'file-type-doc',
    xls: 'file-type-xls',
    xlsx: 'file-type-xls',
    ppt: 'file-type-pps',
    pptx: 'file-type-pps',
    zip: 'file-zip',
    rar: 'file-zip',
    '7z': 'file-zip',
    txt: 'file-type-txt',
    csv: 'file-type-csv',
    avi: 'file-video',
    mp4: 'file-video',
    mov: 'file-video',
    wmv: 'file-video',
    flv: 'file-video',
    mkv: 'file-video',
    webm: 'file-video',
    wav: 'file-audio',
    mpeg: 'file-audio',
    mp3: 'file-audio',
    html: 'file-data',
    xml: 'file-data',
    rtf: 'file-data',
    css: 'file-data',
    js: 'file-data',
    sql: 'file-type-sql',
    psd: 'file-type-psd',
    ai: 'file-type-ai',
    id: 'file-type-id',
    indd: 'file-type-id',
    eps: 'file-type-eps',
    svg: 'file-image'
};
export function getIconForFile(fileName) {
    const ext = fileName.split('.').pop();
    if (!ext) {
        return 'file-page';
    }
    return fileTypeIconMap[ext] || 'file-page';
}
